param([string]$ContractRoot="artifacts",[string]$BundlePath="artifacts\cloud\v59-real-contracts.zip",[Parameter(Mandatory=$true)][string]$Bucket,[string]$ObjectKey="finai/contracts/v59/latest.zip")
$ErrorActionPreference="Stop";Set-Location(Resolve-Path(Join-Path $PSScriptRoot ".."));if(-not $env:FINAI_CONTRACT_SIGNING_KEY){throw "FINAI_CONTRACT_SIGNING_KEY is not set."};python .\scripts\cloud_contract_bundle.py create --contract-root $ContractRoot --output $BundlePath;if($LASTEXITCODE-ne 0){throw "Contract signing failed."};python .\scripts\cloud_contract_bundle.py upload --bundle $BundlePath --bucket $Bucket --key $ObjectKey;if($LASTEXITCODE-ne 0){throw "Cloud upload failed."};Write-Host "Signed real contract bundle uploaded." -ForegroundColor Green
